import type { CodingQuestion, CodingTestCase } from "@/data/codingQuestions";

type QuestionSeed = {
  id: string;
  title: string;
  summary: string;
  difficulty: CodingQuestion["difficulty"];
  studyYears: number[];
  category: string;
  pattern: string;
  companies: string[];
  functionName: string;
  problemStatement: string;
  realWorldExample: string;
  starterCode: string;
  solutionCode: string;
  tests: CodingTestCase[];
};

function makeQuestion(seed: QuestionSeed): CodingQuestion {
  const firstTest = seed.tests[0];
  return {
    ...seed,
    durationMinutes: seed.difficulty === "Hard" ? 50 : seed.difficulty === "Medium" ? 35 : 20,
    acceptance: seed.difficulty === "Hard" ? 34 : seed.difficulty === "Medium" ? 58 : 76,
    xp: seed.difficulty === "Hard" ? 125 : seed.difficulty === "Medium" ? 75 : 40,
    prerequisites: [seed.pattern, "Functions", "Edge cases"],
    learningSteps: [
      "Write down the invariant that should remain true after each step.",
      "Choose the data structure that makes the next operation cheap.",
      "Test the empty, smallest, boundary, and largest valid inputs.",
    ],
    examples: [{
      input: JSON.stringify(firstTest.input),
      output: JSON.stringify(firstTest.expected),
      explanation: "Trace the invariant through this representative case before coding.",
    }],
    constraints: ["Inputs follow the types shown in the examples", "Return a JSON-serializable value", "Do not mutate input unless stated"],
    hints: ["Start with the simplest correct loop or recurrence.", "Look for work that is repeated between neighboring positions.", "Name the invariant before optimizing."],
  };
}

